import{_ as t,o,c as r,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"安卓手机安装","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/android.md","filePath":"deploy/android.md","lastUpdated":1791133906000}'),l={name:"deploy/android.md"};function i(d,a,n,s,h,c){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="安卓手机安装" tabindex="-1">安卓手机安装 <a class="header-anchor" href="#安卓手机安装" aria-label="Permalink to &quot;安卓手机安装&quot;">​</a></h1><p>本篇是安装的详细步骤，包含各种意外情况的处理。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><h3 id="_1-备份存档-强烈建议" tabindex="-1">1. 备份存档（强烈建议） <a class="header-anchor" href="#_1-备份存档-强烈建议" aria-label="Permalink to &quot;1. 备份存档（强烈建议）&quot;">​</a></h3><p>存档位置：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/rncampaignInfo.dat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>用手机自带的文件管理器，或者「MT管理器」这类工具，把这个文件复制一份到别的地方。</p><div class="tip custom-block"><p class="custom-block-title">找不到 Android/data 目录？</p><p>安卓 11 及以上，系统自带的文件管理器可能看不到 <code>Android/data</code>。解决方式：</p><ul><li>用第三方文件管理器（如 MT管理器），它会申请对应权限；</li><li>或者用数据线连电脑，从电脑端复制。</li></ul></div><h3 id="_2-确认手机空间" tabindex="-1">2. 确认手机空间 <a class="header-anchor" href="#_2-确认手机空间" aria-label="Permalink to &quot;2. 确认手机空间&quot;">​</a></h3><p>APK 本体约 <strong>88 MB</strong>，安装后还会展开占空间。<strong>建议至少留 500 MB 空闲</strong>。</p><p>查看方式：设置 → 存储。</p><h3 id="_3-确认包名冲突" tabindex="-1">3. 确认包名冲突 <a class="header-anchor" href="#_3-确认包名冲突" aria-label="Permalink to &quot;3. 确认包名冲突&quot;">​</a></h3><p>如果你手机上已经装了：</p><ul><li><strong>纯汉化版</strong>（<code>final_full_cn.apk</code>）</li><li><strong>英文原版</strong>（<code>eb3cdae*.apk</code>）</li></ul><div class="warning custom-block"><p class="custom-block-title">先卸载英文原版</p><p>如果你装的是英文原版，需要<strong>先卸载它</strong>再装 Mod 版（如果两者签名不同，覆盖安装会失败）。纯汉化版则可以直接覆盖。</p></div><h2 id="二、安装" tabindex="-1">二、安装 <a class="header-anchor" href="#二、安装" aria-label="Permalink to &quot;二、安装&quot;">​</a></h2><h3 id="步骤-1-把-apk-传到手机上" tabindex="-1">步骤 1：把 APK 传到手机上 <a class="header-anchor" href="#步骤-1-把-apk-传到手机上" aria-label="Permalink to &quot;步骤 1：把 APK 传到手机上&quot;">​</a></h3><p>任意方式都可以：数据线、网盘、聊天软件传文件。</p><h3 id="步骤-2-允许「未知来源」" tabindex="-1">步骤 2：允许「未知来源」 <a class="header-anchor" href="#步骤-2-允许「未知来源」" aria-label="Permalink to &quot;步骤 2：允许「未知来源」&quot;">​</a></h3><p>安卓默认不允许安装非应用商店的 APK，需要手动允许：</p><ul><li><strong>安卓 8 及以上</strong>：设置 → 应用 → 特殊应用权限 → 安装未知应用 → 选择你用来打开 APK 的那个应用（文件管理器 / 浏览器）→ 允许。</li><li><strong>安卓 7 及以下</strong>：设置 → 安全 → 未知来源 → 勾选。</li></ul><h3 id="步骤-3-点击-apk-安装" tabindex="-1">步骤 3：点击 APK 安装 <a class="header-anchor" href="#步骤-3-点击-apk-安装" aria-label="Permalink to &quot;步骤 3：点击 APK 安装&quot;">​</a></h3><p>用文件管理器找到 APK，点击 → 安装。</p><p>如果提示「<strong>已存在同名应用，是否替换？</strong>」→ 选<strong>确定</strong>（这是覆盖安装，存档会保留）。</p><h3 id="步骤-4-首次启动" tabindex="-1">步骤 4：首次启动 <a class="header-anchor" href="#步骤-4-首次启动" aria-label="Permalink to &quot;步骤 4：首次启动&quot;">​</a></h3><p>安装完成后点「打开」，或从桌面图标进入。</p><h2 id="三、覆盖安装时的注意事项" tabindex="-1">三、覆盖安装时的注意事项 <a class="header-anchor" href="#三、覆盖安装时的注意事项" aria-label="Permalink to &quot;三、覆盖安装时的注意事项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>会不会丢存档</th><th>说明</th></tr></thead><tbody><tr><td>纯汉化版 → Mod 版</td><td><strong>不会</strong></td><td>包名相同，属于升级</td></tr><tr><td>旧版 Mod → 新版 Mod</td><td><strong>不会</strong></td><td>同上</td></tr><tr><td>英文原版 → Mod 版</td><td>可能会</td><td>如果提示签名冲突必须先卸载</td></tr><tr><td>卸载后重装</td><td><strong>会</strong></td><td>卸载会清掉数据目录</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">卸载前一定要备份</p><p><strong>卸载应用会连数据一起删掉。</strong> 如果一定要卸载，先把 <code>Android/data/&lt;包名&gt;/files/</code> 整个目录复制出来。</p></div><h2 id="四、常见安装问题" tabindex="-1">四、常见安装问题 <a class="header-anchor" href="#四、常见安装问题" aria-label="Permalink to &quot;四、常见安装问题&quot;">​</a></h2><h3 id="「解析包时出现问题」" tabindex="-1">「解析包时出现问题」 <a class="header-anchor" href="#「解析包时出现问题」" aria-label="Permalink to &quot;「解析包时出现问题」&quot;">​</a></h3><p>通常原因：</p><ol><li><strong>下载不完整</strong> —— 重新下载一次，确认文件大小是 ~88 MB（不是几十 KB）。</li><li><strong>安卓版本太低</strong> —— 游戏本体要求安卓 4.0+。</li><li><strong>APK 被安全软件改过</strong> —— 关掉安全软件的「安装拦截」再试。</li></ol><h3 id="「应用未安装」" tabindex="-1">「应用未安装」 <a class="header-anchor" href="#「应用未安装」" aria-label="Permalink to &quot;「应用未安装」&quot;">​</a></h3><ol><li><strong>签名冲突</strong> —— 手机上已有一个签名不同的同包名应用。先卸载那个，再装。</li><li><strong>空间不足</strong> —— 清理空间到 500 MB 以上。</li><li><strong>系统限制</strong> —— 部分定制系统（如某些国产 ROM）需要额外开启「允许安装外部应用」。</li></ol><h3 id="「存储空间不足」" tabindex="-1">「存储空间不足」 <a class="header-anchor" href="#「存储空间不足」" aria-label="Permalink to &quot;「存储空间不足」&quot;">​</a></h3><p>清理相册与聊天软件占用的缓存，或卸载不用的应用。安卓需要「安装包大小 + 展开大小」的空闲空间。</p><h3 id="安装后打不开-秒退" tabindex="-1">安装后打不开 / 秒退 <a class="header-anchor" href="#安装后打不开-秒退" aria-label="Permalink to &quot;安装后打不开 / 秒退&quot;">​</a></h3><p>进战斗前就秒退，通常是<strong>内存不足</strong>。尝试：</p><ol><li>关机重启，清空后台。</li><li>关掉其他占内存的应用。</li><li>如果还是不行，说明设备内存确实不够（游戏本体需求，与框架无关）。</li></ol><p>如果是<strong>进战斗后</strong>闪退，看 <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a>。</p><h2 id="五、装好后的验证" tabindex="-1">五、装好后的验证 <a class="header-anchor" href="#五、装好后的验证" aria-label="Permalink to &quot;五、装好后的验证&quot;">​</a></h2><p>进游戏，按顺序确认：</p><ol><li><strong>能看到悬浮窗</strong>「u」→ 框架已加载。</li><li><strong>点开面板</strong>，切到「状态」页。</li><li>状态页应该显示<strong>没有任何参数偏离原版</strong>。</li></ol><p>如果这些都正常，说明装干净了。接下来去 <a href="/AtlanticFleetSite/docs/deploy/first-run">首次启动与目录</a> 了解框架在磁盘上建了什么，或者直接去 <a href="/AtlanticFleetSite/docs/deploy/install-mod">安装 Mod 的三种方式</a> 装第一个 Mod。</p>',45)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
